defmodule JoobQ.ContextTest do
  use ExUnit.Case, async: true

  alias JoobQ.{Batches, Context, Job, Workflows}
  alias JoobQ.Worker.Outcome

  # Builds, from inside a run, what the handler would send: the bodies carry the running job's context.
  defmodule Starts do
    def perform(_job) do
      enqueued = Job.body("mail", "send", %{}, context: %{trace: "mine"})
      send(self(), {:bodies, enqueued, Workflows.start_body("w", nil, [])})

      :ok
    end
  end

  test "work started inside a run carries the job's context under its own, string keys" do
    job = %JoobQ.Job{context: %{"tenant" => "t1", "trace" => "job"}}
    assert Outcome.run(Starts, job)["outcome"] == "complete"

    assert_received {:bodies, enqueued, started}
    assert enqueued["context"] == %{"tenant" => "t1", "trace" => "mine"}
    assert started["context"] == %{"tenant" => "t1", "trace" => "job"}
    assert Context.current() == %{}
    refute Map.has_key?(Job.body("q", "t"), "context")
  end

  test "a batch: the job's context under the batch's, under each member's; a member without one keeps it" do
    Context.put(%{"tenant" => "t1", "trace" => "job"})

    members = [{"q", "t", %{}, context: %{"m" => 1}}, {"q", "t", %{}, context: nil}]
    body = Batches.body(members, context: %{trace: "batch"})

    Context.clear()

    assert [%{"context" => first}, %{"context" => second}] = body["jobs"]
    assert first == %{"tenant" => "t1", "trace" => "batch", "m" => 1}
    assert second == %{"tenant" => "t1", "trace" => "batch"}
  end

  test "merging turns atom keys into strings, so one key is sent once" do
    assert Context.merge(%{tenant: "a"}, %{"tenant" => "b"}) == %{"tenant" => "b"}
    assert Context.merge(%{"tenant" => "a"}, nil) == %{"tenant" => "a"}
  end

  defmodule Secrets do
    defstruct api_key: "sk_live_SECRET"
  end

  test "a struct as a context is never walked nor printed: the body encoding refuses it by its kind" do
    struct = %Secrets{}

    bodies = [
      fn -> Batches.body([{"q", "t", %{}, [context: struct]}], context: %{"t" => 1}) end,
      fn -> Batches.body([{"q", "t", %{}, [context: %{"t" => 2}]}], context: struct) end,
      fn ->
        Context.put(%{"tenant" => "t1"})
        Job.body("q", "t", %{}, context: struct)
      end,
      fn -> Workflows.start_body("w", nil, context: struct) end
    ]

    for body <- bodies do
      built = body.()
      Context.clear()

      assert {:error, %JoobQ.Error{reason: :invalid, code: "unencodable_body"} = error} =
               JoobQ.Transport.encode(built)

      refute Exception.message(error) =~ "SECRET"
    end

    Context.put(struct)
    assert Context.current() == %{}
  end
end
